                    this.hangarShipId,
                    'wing',
                    h.drag.startScaleX + (hasX ? outward : 0) / Math.max(1, h.drag.frameWidth),
                    h.drag.startScaleY + (hasY ? heightSign * dy : 0) / Math.max(1, h.drag.frameHeight)
