                this.hangarShipId,
                h.drag.segment,
                h.drag.startScaleX + (2 * widthSign * dx) / Math.max(1, h.drag.frameWidth || h.core.width),
                h.drag.startScaleY + (heightSign * dy) / Math.max(1, h.drag.frameHeight || h.core.height)
