        // Cast shadow on the cell floor.
        const mx = 2, my = 2, bw = cw - mx * 2 - 1, bh = ch - my * 2 - 1;
        for (let x = mx + 2; x < mx + bw; x++) for (let y = my + bh - 2; y <= my + bh + 1; y++) dot(x, y, [0, 0, 0], 0.5);
        const cx = Math.floor(cw / 2), tall = ch > cw * 1.3;

